import Database from 'better-sqlite3';
const db = new Database('audit.db');
db.pragma('journal_mode = WAL');
const insert = db.prepare('INSERT OR IGNORE INTO msg_store VALUES (?,?,?,?)');
const flush = db.transaction((rows) => {
    for (const r of rows) insert.run(r.id, r.chan, r.at, r.body);
});
const buffer = [];
function tap(rec) {                    // request path: enqueue only, never write
    buffer.push(rec);
    if (buffer.length >= 500) flush(buffer.splice(0));
}
